<script setup>
import {computed,watchEffect} from 'vue';import {useRoute} from 'vue-router';import {useMovies} from '../composables/useMovies.js';import MovieCard from '../components/MovieCard.vue';import AppIcon from '../components/AppIcon.vue';
const route=useRoute();const {movies,loading,error,loadMovies,isFavorite,toggleFavorite}=useMovies();const movie=computed(()=>movies.value.find(m=>m.id===Number(route.params.id)));const related=computed(()=>movies.value.filter(m=>m.id!==movie.value?.id).sort((a,b)=>Number(b.genre===movie.value?.genre)-Number(a.genre===movie.value?.genre)).slice(0,4));const base=import.meta.env.BASE_URL;watchEffect(()=>{document.title=movie.value?`${movie.value.title} · FRAME`:'Film · FRAME';});
</script>
<template><div class="detail-page"><RouterLink to="/" class="back-link"><AppIcon name="back"/>Back to the collection</RouterLink><div v-if="loading" class="empty-state" aria-live="polite"><p>Loading the story…</p></div><div v-else-if="error" class="empty-state" role="alert"><h1>A brief intermission.</h1><p>{{error}}</p><button class="button amber" @click="loadMovies">Try again</button></div><template v-else-if="movie"><section class="movie-detail"><img class="detail-poster" :src="base+movie.poster" :alt="`${movie.title} concept poster`"><div class="detail-info"><span class="eyebrow">THE FRAME COLLECTION / {{String(movie.id).padStart(2,'0')}}</span><div class="detail-tags"><span>{{movie.genre}}</span><span>{{movie.year}}</span><span><AppIcon name="clock"/>{{movie.duration}} min</span></div><h1>{{movie.title}}</h1><p class="detail-tagline">{{movie.tagline}}</p><div class="detail-rating"><AppIcon name="star"/><strong>{{movie.rating.toFixed(1)}}</strong><span>/ 10 <small>Illustrative demo rating</small></span></div><h2>The story</h2><p class="synopsis">{{movie.description}}</p><dl><div><dt>DIRECTOR</dt><dd>{{movie.director}}</dd></div><div><dt>STARRING</dt><dd>{{movie.cast.join(', ')}}</dd></div><div><dt>LANGUAGE</dt><dd>{{movie.language}}</dd></div></dl><button class="button" :class="{amber:!isFavorite(movie.id)}" @click="toggleFavorite(movie.id)" :aria-pressed="isFavorite(movie.id)"><AppIcon :name="isFavorite(movie.id)?'check':'bookmark'"/>{{isFavorite(movie.id)?'Saved to your watchlist':'Add to watchlist'}}</button><p class="detail-disclaimer">Fictional film and cast. Original artwork. No streaming available.</p></div></section><section class="related"><div class="related-heading"><h2>Keep the story going.</h2><RouterLink to="/">See all films ↗</RouterLink></div><div class="movie-grid"><MovieCard v-for="item in related" :key="item.id" :movie="item"/></div></section></template><div v-else class="empty-state"><AppIcon name="film"/><h1>This film isn’t in our collection.</h1><p>The link may be incorrect. There are more stories to discover.</p><RouterLink to="/" class="button amber">Explore films</RouterLink></div></div></template>
